from pathlib import Path
D={}
for side in ('left','right'):
 a=[]
 for line in Path(f'output/work/{side}_motion.tsv').open():
  t,v=map(float,line.split()); a.append((t,v))
 D[side]=a
for lo,hi in [(14,21),(25,32),(42,55),(61,67),(70,85)]:
 print('\\nINTERVAL',lo,hi)
 for side,a in D.items():
  b=[x for x in a if lo<=x[0]<=hi]
  # maxima over +-4 frames; only strongest > 1.5, separated .25
  peaks=[]
  for i in range(4,len(b)-4):
   t,v=b[i]
   if v==max(x[1] for x in b[i-4:i+5]) and v>1.5:
    if not peaks or t-peaks[-1][0]>.25: peaks.append((t,v))
    elif v>peaks[-1][1]: peaks[-1]=(t,v)
  print(side,' '.join(f'{t:.2f}:{v:.1f}' for t,v in peaks))
PY"

